usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.VectorStores.Search(
		context.TODO(),
		"vs_abc123",
		openai.VectorStoreSearchParams{
			Query: "string",
			RewriteQuery: param.NewOpt[bool](false),
			MaxNumResults: param.NewOpt[int64](10),
			Filters: openai.ComparisonFilter{Type: openai.ComparisonFilterTypeEq, Key: "string", Value: "string"},
			RankingOptions: openai.VectorStoreSearchRequestRankingOptions{Ranker: openai.VectorStoreSearchRequestRankingOptionsRankerNone, ScoreThreshold: 0},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
